  m2 : mat4x4<f32>,
  m3 : mat4x4<f32>,
  view : mat4x4<f32>,
  splitPlanes : vec4<f32>,
  cascadeCount : u32,
  probePadA : u32,
  probePadB : u32,
  probePadC : u32,
